const countryMap = {
  // Chile
  chile: 'CL',
  cl: 'CL',
  chl: 'CL',
  // Argentina
  argentina: 'AR',
  ar: 'AR',
  arg: 'AR',
  // Bolivia
  bolivia: 'BO',
  bo: 'BO',
  bol: 'BO',
  // Perú
  peru: 'PE',
  'perú': 'PE',
  pe: 'PE',
  per: 'PE',
};

const vehicleMap = {
  camion: 'hgv',
  'camión': 'hgv',
  coche: 'car',
};

const truckSubtypeMap = {
  general: '',
  autobus: 'bus',
  'autobús': 'bus',
  'agrícola': 'agricultural',
  agricola: 'agricultural',
  forestal: 'forestry',
  reparto: 'delivery',
  'mercancía': 'goods',
  mercancia: 'goods',
};

function normalizeText(value) {
  return String(value || '').trim().toLowerCase();
}

function detectCountryFromAddress(address) {
  const text = normalizeText(address);
  if (text.includes('chile')) return 'CL';
  if (text.includes('argentina')) return 'AR';
  if (text.includes('bolivia')) return 'BO';
  if (text.includes('peru') || text.includes('perú')) return 'PE';
  return null;
}

return items.map(item => {
  const data = item.json;

  const pickupCountry =
    countryMap[normalizeText(data.pickup_acountryCode)] ||
    detectCountryFromAddress(data.pickup_address) ||
    'CL'; // ← default CL si todo lo anterior es null/vacío

  const destinationCountry =
    countryMap[normalizeText(data.destination_countryCode)] ||
    detectCountryFromAddress(data.destination_address);

  const vehiculo =
    vehicleMap[normalizeText(data.vehiculo)] || data.vehiculo;

  // Si subtipo es null/undefined/vacío → siempre ''
  const subtipoNormalizado = normalizeText(data.subtipo_camion);
  const subtipoCamion = !subtipoNormalizado
    ? ''
    : (truckSubtypeMap[subtipoNormalizado] ?? data.subtipo_camion);

  return {
    json: {
      ...data,
      pickup_acountryCode: pickupCountry,
      destination_countryCode: destinationCountry,
      vehiculo,
      subtipo_camion: subtipoCamion,
    }
  };
});

/**
 * ================================================================================
 *  FASE 3: SCORING MULTICRITERIO (Motor de Decision)
 * ================================================================================
 *  Este script se coloca DESPUES del nodo HTTP de Matrix.
 *  Cruza los datos del prefiltro con la matriz de distancias reales,
 *  calcula el score final ponderado y emite el ganador.
 */

const item = $input.all()[0].json;

if (item.status === "sin_pasos") {
    return [{ json: item }]; // Pasa directo el fallback
}

// Obtener la matriz del nodo actual (Fase 2)
let mat = $input.all()[0].json;
if (mat.body && mat.body.distances) {
    mat = mat.body; // Si usamos Full Response
} else if (mat.ors_matrix_response) {
    mat = mat.ors_matrix_response.body || mat.ors_matrix_response;
}

// OBTENER LA DATA DEL NODO FASE 1
let fase1;
try {
    fase1 = $("Fase 1").first().json;
} catch (e) {
    throw new Error("Por favor, renombra tu primer nodo Code a 'Fase 1' para que este script pueda leer sus datos.");
}

// OBTENER DATOS DE VEHÍCULO DEL NODO COMPACT
let compactNode;
try {
    compactNode = $("Compact").first().json;
} catch (e) {
    throw new Error("No se pudo leer el nodo 'Compact'. Verifica el nombre.");
}
const vehiculo_real = compactNode.vehiculo || "";
const subtipo_real = compactNode.subtipo_camion || "";

const config = fase1.config;
const topCandidatos = fase1.top_candidatos;

if (!mat || !mat.distances) throw new Error("No se recibio respuesta valida de ORS Matrix");

// Extraemos la distancia directa Vial (A -> C) para normalizar.
// En nuestra matriz: A es index 0 en sources. C es el ultimo index en destinations.
const idxAC_source = 0;
const idxAC_dest = topCandidatos.length; 
const dAC_vial_km = mat.distances[idxAC_source][idxAC_dest];
const tAC_vial_s  = mat.durations[idxAC_source][idxAC_dest];

function calcIDR(dAB, dBC, dAC) { return (dAC > 0) ? (dAB + dBC) / dAC : Infinity; }

const candidatosEvaluados = topCandidatos.map((paso, i) => {
    // A -> B[i]: Source index 0, Dest index i
    const dAB_km = mat.distances[0][i];
    const tAB_s  = mat.durations[0][i];

    // B[i] -> C: Source index i+1, Dest index idxAC_dest
    const dBC_km = mat.distances[i + 1][idxAC_dest];
    const tBC_s  = mat.durations[i + 1][idxAC_dest];

    const totalKm = dAB_km + dBC_km;
    const totalS  = tAB_s  + tBC_s;
    const IDR_vial = calcIDR(dAB_km, dBC_km, dAC_vial_km);

    // Funcion de costo base
    const ref = dAC_vial_km > 0 ? dAC_vial_km : 1;
    const tRef = tAC_vial_s  > 0 ? tAC_vial_s  : 1;
    const scoreBase = config.WEIGHTS.wDist * (totalKm / ref)
                    + config.WEIGHTS.wIDR  * IDR_vial
                    + config.WEIGHTS.wTime * (totalS  / tRef);

    const penalizacion = config.ESTADO_PENALTY[paso.estado_operativo] ?? 1.0;
    const scoreFinal = scoreBase * penalizacion;

    return {
        ...paso,
        distancia_origen_km:  Math.round(dAB_km * 10) / 10,
        distancia_destino_km: Math.round(dBC_km * 10) / 10,
        total_vial_km:        Math.round(totalKm * 10) / 10,
        tiempo_origen_min:    Math.round(tAB_s / 60),
        tiempo_destino_min:   Math.round(tBC_s / 60),
        total_tiempo_min:     Math.round(totalS / 60),
        IDR_vial:             Math.round(IDR_vial * 10000) / 10000,
        penalizacion_estado:  penalizacion,
        score:                Math.round(scoreFinal * 10000) / 10000,
    };
});

candidatosEvaluados.sort((a, b) => a.score - b.score);
const optimo = candidatosEvaluados[0];
const alternativo = candidatosEvaluados.length > 1 ? candidatosEvaluados[1] : null;

const gHaversine = fase1.ganador_haversine;
const gVincenty = fase1.ganador_vincenty;
const coinciden = gHaversine.nombre === gVincenty.nombre && gVincenty.nombre === optimo.nombre;

return [{
    json: {
        vehiculo: vehiculo_real,
        subtipo_camion: subtipo_real,
        metadata: {
            motor: "FrontierAdvice Decision Engine v2.0 (Split Arch)",
            perfil_ors: config.profile,
            tipo_vehiculo: config.tipoVehiculo,
            distancia_directa_vial_km: Math.round(dAC_vial_km * 10) / 10,
        },
        paso_seleccionado: {
            documentId:           optimo.documentId,
            nombre:               optimo.nombre,
            estado_operativo:     optimo.estado_operativo,
            total_vial_km:        optimo.total_vial_km,
            total_tiempo_min:     optimo.total_tiempo_min,
            IDR_vial:             optimo.IDR_vial,
            score:                optimo.score,
        },
        top3_alternativas: candidatosEvaluados.slice(0, 3).map(p => ({
            nombre:             p.nombre,
            estado_operativo:   p.estado_operativo,
            total_vial_km:      p.total_vial_km,
            total_tiempo_min:   p.total_tiempo_min,
            score:              p.score,
        })),
        comparativa_metodos: {
            haversine_seleccionaria:      gHaversine.nombre,
            vincenty_puro_seleccionaria:  gVincenty.nombre,
            motor_decision_selecciono:    optimo.nombre,
            los_tres_coinciden:           coinciden,
            diferencia_km_haversine_vs_motor: isFinite(gHaversine.km)
                ? Math.round((optimo.total_vial_km - gHaversine.km) * 10) / 10
                : null
        },
        // Waypoints listos para el nodo ORS Directions Final (Branch B)
        ors_waypoints: [
            [config.oLon, config.oLat],
            [optimo._bLon, optimo._bLat],
            [config.dLon, config.dLat]
        ],
        ors_alternative_waypoints: alternativo ? [
            [config.oLon, config.oLat],
            [alternativo._bLon, alternativo._bLat],
            [config.dLon, config.dLat]
        ] : null
    }
}];

/**
 * ================================================================================
 *  FASE 1: PRE-FILTRO GEODESICO (Motor de Decision)
 * ================================================================================
 *  Este script 
 *  Filtra pasos cerrados/incompatibles, calcula Vincenty, elige el Top 3,
 *  y genera el payload exacto para enviar a la API de Matrix en un solo request.
 */

const TOP_N = 3;
const IDR_MAX = 2.5;

// Variables y pesos (se pasan a la siguiente fase)
const WEIGHTS = { wDist: 0.50, wIDR: 0.30, wTime: 0.20 };
const ESTADO_PENALTY = {
    'abierto': 1.00, 'open': 1.00,
    'precaucion': 1.30, 'caution': 1.30,
    'cerrado': Infinity, 'closed': Infinity,
};
const VEHICULOS_PESADOS = new Set([
    'camion', 'camion_reparto', 'camion_agricola',
    'camion_mercancias', 'camion_forestal', 'bus', 'hgv'
]);

// ─── MATEMATICA GEODESICA ──────────────────────────────────────────────────────
function haversineKm(la1, lo1, la2, lo2) {
    const R = 6371; const r = d => d * Math.PI / 180;
    const a = Math.sin(r(la2-la1)/2)**2 + Math.cos(r(la1))*Math.cos(r(la2))*Math.sin(r(lo2-lo1)/2)**2;
    return R * 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1-a));
}

const _W = { a: 6378137.0, f: 1/298.257223563, b: 6356752.314245 };
function vincentyKm(la1, lo1, la2, lo2) {
    const { a, f, b } = _W; const R = d => d * Math.PI / 180;
    const phi1=R(la1), phi2=R(la2), L=R(lo2-lo1);
    const tU1=(1-f)*Math.tan(phi1), tU2=(1-f)*Math.tan(phi2);
    const cU1=1/Math.sqrt(1+tU1*tU1), sU1=tU1*cU1;
    const cU2=1/Math.sqrt(1+tU2*tU2), sU2=tU2*cU2;
    let lam=L, lP, sS, cS, sg, sA, c2A, c2Sm, C, it=0;
    do {
        const sL=Math.sin(lam), cL=Math.cos(lam);
        const ss=(cU2*sL)**2+(cU1*sU2-sU1*cU2*cL)**2;
        sS=Math.sqrt(ss); if(sS===0) return 0;
        cS=sU1*sU2+cU1*cU2*cL; sg=Math.atan2(sS,cS);
        sA=cU1*cU2*sL/sS; c2A=1-sA*sA;
        c2Sm=c2A!==0?cS-2*sU1*sU2/c2A:0;
        C=f/16*c2A*(4+f*(4-3*c2A)); lP=lam;
        lam=L+(1-C)*f*sA*(sg+C*sS*(c2Sm+C*cS*(-1+2*c2Sm**2)));
        if(++it>100) return haversineKm(la1,lo1,la2,lo2); // fallback
    } while(Math.abs(lam-lP)>1e-12);
    const u2=c2A*(a*a-b*b)/(b*b);
    const Av=1+u2/16384*(4096+u2*(-768+u2*(320-175*u2)));
    const Bv=u2/1024*(256+u2*(-128+u2*(74-47*u2)));
    const ds=Bv*sS*(c2Sm+Bv/4*(cS*(-1+2*c2Sm**2)-Bv/6*c2Sm*(-3+4*sS**2)*(-3+4*c2Sm**2)));
    return b*Av*(sg-ds)/1000;
}

// ─── HELPERS ───────────────────────────────────────────────────────────────────
function calcIDR(dAB, dBC, dAC) { return (dAC > 0) ? (dAB + dBC) / dAC : Infinity; }
function estadoDePaso(p) { return (p.estado_general || p.estado || p.status || 'abierto').toLowerCase(); }
function esCompatible(p, tipoVehiculo) {
    if (!tipoVehiculo) return true;
    const habs = p.habilitado_para || p.habilitadoPara || p.allowed_for;
    if (!habs || !Array.isArray(habs) || habs.length === 0) return true;
    const tv = tipoVehiculo.toLowerCase();
    return habs.some(h => {
        const hl = (h || '').toLowerCase();
        return hl === tv || (tv.includes('camion') && hl.includes('camion')) || hl.includes('todo tipo');
    });
}

// ─── PROCESAMIENTO ─────────────────────────────────────────────────────────────
const item = $input.all()[0].json;
if (!item.origen || !item.destino) throw new Error("Faltan campos origen/destino.");

const oLat = parseFloat(item.origen.latitude ?? item.origen.latitud);
const oLon = parseFloat(item.origen.longitude ?? item.origen.longitud);
const dLat = parseFloat(item.destino.latitude ?? item.destino.latitud);
const dLon = parseFloat(item.destino.longitude ?? item.destino.longitud);
const tipoVehiculo = (item.tipo_vehiculo || item.vehiculo || '').toLowerCase();
const profile = VEHICULOS_PESADOS.has(tipoVehiculo) ? 'driving-hgv' : 'driving-car';

let pasos = item.pasos_fronterizos ?? item.data ?? [];

// 1. Filtrar estado y compatibilidad
const pasosFiltrados = pasos.filter(p => {
    if (ESTADO_PENALTY[estadoDePaso(p)] === Infinity) return false;
    if (!esCompatible(p, tipoVehiculo)) return false;
    return true;
});

if (!pasosFiltrados.length) {
    return [{ json: { status: "sin_pasos", mensaje: "No hay pasos viables." } }];
}

// 2. Calculo Geodesico
const dAC_geo = vincentyKm(oLat, oLon, dLat, dLon);
const evaluados = pasosFiltrados.map(p => {
    const bLat = parseFloat(p.latitud ?? p.lat);
    const bLon = parseFloat(p.longitud ?? p.lon ?? p.lng);
    const nombre = p.nombre_oficial ?? p.nombre ?? `ID-${p.id}`;
    if (isNaN(bLat) || isNaN(bLon)) return { ...p, nombre, IDR_geo: Infinity };

    const dAB = vincentyKm(oLat, oLon, bLat, bLon);
    const dBC = vincentyKm(bLat, bLon, dLat, dLon);
    const hAB = haversineKm(oLat, oLon, bLat, bLon);
    const hBC = haversineKm(bLat, bLon, dLat, dLon);

    return {
        ...p, nombre, _bLat: bLat, _bLon: bLon, estado_operativo: estadoDePaso(p),
        total_haversine_km: hAB + hBC,
        total_vincenty_km: dAB + dBC,
        IDR_geo: calcIDR(dAB, dBC, dAC_geo)
    };
});

evaluados.sort((a, b) => a.IDR_geo - b.IDR_geo);
const ganadorVincenty = evaluados[0];
const ganadorHaversine = [...evaluados].sort((a,b) => a.total_haversine_km - b.total_haversine_km)[0];

const topCandidatos = evaluados.filter(p => p.IDR_geo <= IDR_MAX).slice(0, TOP_N);
if (!topCandidatos.length) throw new Error("Ningun paso supera umbral IDR.");

// 3. Preparar payload de matriz para UN SOLO request HTTP
// Array [Origen, Cand1, Cand2, Cand3, Destino]
const locations = [
    [oLon, oLat],
    ...topCandidatos.map(p => [p._bLon, p._bLat]),
    [dLon, dLat]
];
const N = topCandidatos.length;
const sources = [0, ...topCandidatos.map((_, i) => i + 1)]; // A y todos los B
const destinations = [...topCandidatos.map((_, i) => i + 1), N + 1]; // Todos los B y C

return [{
    json: {
        status: "ok",
        metadata_prefiltro: { dAC_geo, total_pasos: pasos.length },
        config: { WEIGHTS, ESTADO_PENALTY, profile, tipoVehiculo, oLon, oLat, dLon, dLat },
        top_candidatos: topCandidatos,
        ganador_haversine: { nombre: ganadorHaversine.nombre, km: ganadorHaversine.total_haversine_km },
        ganador_vincenty: { nombre: ganadorVincenty.nombre, km: ganadorVincenty.total_vincenty_km },

        // ESTO LO LEE EL NODO HTTP DIRECTAMENTE
        ors_matrix_payload: {
            locations,
            sources,
            destinations,
            metrics: ["distance", "duration"],
            units: "km"
        }
    }
}];

// Input esperado en este nodo:
// [
//   { p_longitude, p_latitude, ... },
//   { d_longitude, d_latitude, ... }
// ]

const normalizacion = $('Normalización').first().json;

const origenItem = items.find(item =>
  item.json.p_longitude != null && item.json.p_latitude != null
);

const destinoItem = items.find(item =>
  item.json.d_longitude != null && item.json.d_latitude != null
);

if (!origenItem) {
  throw new Error('No se encontró el origen (p_longitude / p_latitude)');
}

if (!destinoItem) {
  throw new Error('No se encontró el destino (d_longitude / d_latitude)');
}

return [
  {
    json: {
      origen: {
        longitude: Number(origenItem.json.p_longitude),
        latitude: Number(origenItem.json.p_latitude),
      },
      destino: {
        longitude: Number(destinoItem.json.d_longitude),
        latitude: Number(destinoItem.json.d_latitude),
      },
      vehiculo: normalizacion.vehiculo,
      subtipo_camion: normalizacion.subtipo_camion,
    }
  }
];

// Input directo: Get Pasos_Fronterizos
const pasosData = $input.first().json.data ?? [];

// Nodo anterior: Packaging
const packaging = $('Packaging').first()?.json ?? {};

// Deduplicar por documentId
const seen = new Set();
const pasosFronterizos = [];

for (const paso of pasosData) {
  if (!paso?.documentId || seen.has(paso.documentId)) continue;
  seen.add(paso.documentId);

  pasosFronterizos.push({
    documentId: paso.documentId,
    nombre: paso.nombre_oficial,
    latitud: paso.latitud,
    longitud: paso.longitud,
    activo: paso.activo,
    habilitado_para: Array.isArray(paso.habilitado_para) ? paso.habilitado_para : []
  });
}

return [
  {
    json: {
      origen: {
        longitude: packaging.origen?.longitude ?? null,
        latitude: packaging.origen?.latitude ?? null
      },
      destino: {
        longitude: packaging.destino?.longitude ?? null,
        latitude: packaging.destino?.latitude ?? null
      },
      vehiculo: packaging.vehiculo ?? null,
      subtipo_camion: packaging.subtipo_camion ?? null,
      pasos_fronterizos: pasosFronterizos
    }
  }
];
